INSERT INTO "messages" ("id","visitor_name","visitor_email","visitor_ip","user_agent","client_hash","content","quoted_text","page_url","page_title","status","is_deleted","needs_review","created_at","updated_at","reply_content","reply_at","reply_token","visitor_website") VALUES(30,'长安','lice@lice.pw','115.227.218.105','Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/152.0.0.0 Safari/537.36 Edg/152.0.0.0','',replace('August slipped away\nInto a moment in time\n以霉霉的August结束八月。\n今天仅用半上午结完八月账单，报税、缴纳社保、出财报，是最为迅速的一次。\n下午单位组织看电影，《欢迎来龙餐馆》，一部反战题材的电影，还不错。','\n',char(10)),'','https://blog.icecome.com/pages/guestbook/','访客留言 | 三无亦拾吾','approved',0,1,'2026-09-01 11:16:19','2026-09-01 12:58:23',replace('最近看到很多人都在推荐这部电影，看来我也该看看。\n虽然上午有些状态不在，但是下午还是非常棒的，阳光好，心情好，精神好。','\n',char(10)),'2026-09-01 12:58:23','c51e53792cb2d935fb1c39ec44ae2684','https://blog.icecome.com/');
